Definition cb_pieces (k n sz : nat) (bs : list byte) : list cell :=
  (if Nat.eqb k 0 then [] else [CB k (firstn k bs)])
  ++ CB n (firstn n (skipn k bs))
  :: (if Nat.eqb (k + n) sz then [] else [CB (sz - k - n) (skipn (k + n) bs)]).

